// AGGREGATION: has Stocks — stocks survive portfolio liquidation
package com.bank.relations.aggregation;

import java.util.ArrayList;
import java.util.List;

public class Portfolio {
    private final String portfolioId;
    private final List<Stock> stocks = new ArrayList<>();

    public Portfolio(String portfolioId) { this.portfolioId = portfolioId; }

    public void addStock(Stock stock) { stocks.add(stock); }

    public List<Stock> liquidate() {
        List<Stock> surviving = new ArrayList<>(stocks);
        stocks.clear();
        return surviving;  // stocks LIVE ON!
    }

    public int getStockCount() { return stocks.size(); }
    public String getPortfolioId() { return portfolioId; }
}
