// COMPOSITION: owns OrderLines — lines destroyed on cancellation
package com.bank.relations.composition;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

public class TradeOrder {
    private final String orderId;
    private final List<OrderLine> lines = new ArrayList<>();
    private String status = "OPEN";

    public TradeOrder(String orderId) { this.orderId = orderId; }

    public void addLine(String symbol, int qty, BigDecimal price) {
        lines.add(new OrderLine(orderId + "-L" + (lines.size() + 1), symbol, qty, price));
    }

    public void cancel() {
        status = "CANCELLED";
        lines.clear();  // lines DESTROYED — composition!
    }

    public int getLineCount() { return lines.size(); }
    public String getStatus() { return status; }
    public List<OrderLine> getLines() { return List.copyOf(lines); }
}
