// ─── File: src/test/java/com/bank/relations/ThreeRelationshipsTest.java ───
package com.bank.relations;

import com.bank.relations.association.*;
import com.bank.relations.aggregation.*;
import com.bank.relations.composition.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class ThreeRelationshipsTest {

    // ═══ ASSOCIATION: independent services ═══
    @Test
    void association_servicesIndependent() {
        MarketDataProvider mdp = new MarketDataProvider();
        TradeService service = new TradeService(mdp);
        assertThat(service.calculateValue("RELIANCE", 100)).isEqualByComparingTo("245050");
        // TradeService and MarketDataProvider are independent.
        // Replace mdp with mock → TradeService still works. No lifecycle coupling.
    }

    // ═══ AGGREGATION: parts survive whole's destruction ═══
    @Test
    void aggregation_stocksSurvivePortfolioLiquidation() {
        Stock reliance = new Stock("RELIANCE", 100, new BigDecimal("2450"));
        Stock tcs = new Stock("TCS", 50, new BigDecimal("3520"));

        Portfolio portfolio = new Portfolio("PF-001");
        portfolio.addStock(reliance);
        portfolio.addStock(tcs);

        List<Stock> survivors = portfolio.liquidate();
        assertThat(portfolio.getStockCount()).isZero();       // portfolio empty
        assertThat(survivors).hasSize(2);                     // stocks ALIVE!
        assertThat(reliance.getSymbol()).isEqualTo("RELIANCE"); // still exists!
    }

    // ═══ COMPOSITION: parts destroyed with whole ═══
    @Test
    void composition_linesDestroyedOnOrderCancel() {
        TradeOrder order = new TradeOrder("ORD-001");
        order.addLine("RELIANCE", 100, new BigDecimal("2450"));
        order.addLine("TCS", 50, new BigDecimal("3520"));
        assertThat(order.getLineCount()).isEqualTo(2);

        order.cancel();
        assertThat(order.getLineCount()).isZero();    // lines DESTROYED!
        assertThat(order.getStatus()).isEqualTo("CANCELLED");
    }

    // ═══ THE KEY DIFFERENCE: lifecycle ═══
    @Test
    void lifecycleComparison() {
        // ASSOCIATION: no lifecycle coupling (both independent)
        // AGGREGATION: parent destroyed → parts SURVIVE
        // COMPOSITION: parent destroyed → parts DESTROYED
        Stock stock = new Stock("RELIANCE", 100, new BigDecimal("2450"));
        Portfolio pf = new Portfolio("PF-001");
        pf.addStock(stock);
        pf.liquidate();
        assertThat(stock.getSymbol()).isEqualTo("RELIANCE");  // ALIVE!

        TradeOrder order = new TradeOrder("ORD-001");
        order.addLine("RELIANCE", 100, new BigDecimal("2450"));
        order.cancel();
        assertThat(order.getLineCount()).isZero();  // DESTROYED!
    }
}
```
